steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      teams(key: \"ENG\") {
        id
        name
        cycles {
          id
          name
        }
      }
      issue(identifier: \"ENG-9\") {
        id
        identifier
        title
        cycle {
          id
          name
        }
      }
    }"
  }'
